{"CommandLine":"Get-PSDrive -PSProvider FileSystem | ForEach-Object {
    $root = $_.Root
    Write-Host "Drive: $root"
    Get-ChildItem -Path $root -Filter "*Evoca*" -Recurse -ErrorAction SilentlyContinue | Select-Object FullName, Length, LastWriteTime
}
# Also check C:\Users\andre\Downloads and C:\Users\andre\Desktop
Get-ChildItem -Path "C:\Users\andre\Downloads","C:\Users\andre\OneDrive\Desktop" -Filter "*Evoca*" -Recurse -ErrorAction SilentlyContinue | Select-Object FullName, Length, LastWriteTime","WaitMsBeforeAsync":5000,"toolSummary":"Find all B866V2-FlashATV12 - Evoca.bat across all drives and folders"}
